    private void api(){LinearLayout form=a.fullPage("AI 识别接口",a::home);form.addView(Ui.help(a,"兼容 Chat Completions。仅在你主动点击识别时发送所选内容。"));TextInputEditText url=Ui.field(a,form,"API 根地址，例如 https://host/v1",p.getString("api_url",""),false),model=Ui.field(a,form,"模型名称",p.getString("model",""),false),key=Ui.field(a,form,"API Key（留空保留原密钥）","",false);key.setInputType(129);form.addView(Ui.button(a,"保存接口",true,()->{try{String endpoint=Network.endpoint(url.getText().toString(),true);if(!key.getText().toString().isEmpty())Secrets.put(a,"api_key",key.getText().toString());p.edit().putString("api_url",endpoint).putString("model",model.getText().toString()).apply();a.message("已保存接口");}catch(Exception e){a.message(e.getMessage());}}));}
